public class Speed {
    public static void main(String[] args) {
        long start = System.nanoTime();
        long total = 0;
        for (int i = 0; i < 10_000_000; i++) {
            total += (long) i * i % 7;
        }
        System.out.printf("%d %.2f s%n", total, (System.nanoTime() - start) / 1e9);
    }
}
